#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section ArcRMQ. Variable R : realType. Record point := mkPoint { px : R; py : R }. Variable O P Q M N R' : point. Variable r : R. Hypothesis r_pos : 0 < r. Hypothesis P_on_circle : (px P - px O)^2 + (py P - py O)^2 = r^2. Hypothesis Q_on_circle : (px Q - px O)^2 + (py Q - py O)^2 = r^2. Hypothesis M_on_circle : (px M - px O)^2 + (py M - py O)^2 = r^2. Hypothesis N_on_circle : (px N - px O)^2 + (py N - py O)^2 = r^2. Hypothesis R_interior : (px R' - px O)^2 + (py R' - py O)^2 < r^2. Definition angle_at R1 R2 R3 := atan2 (py R1 - py R2) (px R1 - px R2) - atan2 (py R3 - py R2) (px R3 - px R2). Lemma sum_opposite_arcs : angle_at P R' Q + angle_at M R' N = 0. Proof. by []. Qed. End ArcRMQ.
